\begin{equation}\label{E: splitting}
F_m(\hat t, \lambda, x) = \sum_{\gamma \in M(\Gamma), v \in M(f)} B(\gamma, v) \tilde \pi^{( w_\Gamma(\gamma) + w(v)) / p^{m-1}} \lambda^\gamma x^v,
\end{equation}
with $ord_p \> B(\gamma, r) \geq 0$, and set $\mathcal{B}^m(\gamma,v) =  B(\gamma, v) \tilde \pi^{( w_\Gamma(\gamma) + w(v)) / p^{m-1}} $. So
\begin{align*}
\alpha_m( \tilde \pi^{w(u)} x^u) &= \psi_x^m \left( F_m(\hat t, \lambda, x) \cdot \tilde \pi^{w(u)} x^u \right) \\
&= \sum  \tilde \pi^{(w_\Gamma(\gamma) + w(p^m v - u)) / p^{m-1} + w(u) - w_\Gamma(\gamma)/p^{m-1} - w(v)} B(\gamma, p^m v - u) \cdot \tilde \pi^{w_\Gamma(\gamma) / p^{m-1}} \lambda^\gamma \cdot \tilde \pi^{w(v)} x^v.
\end{align*}
We note that
\begin{align*}
\frac{w(p^m v - u)}{p^{m-1}} + w(u) - w(v) &\geq p w(v) - \frac{w(u)}{p^{m-1}} + w(u) - w(v) \\
&\geq (p-1) w(v) + \frac{p^{m-1}-1}{p^{m-1}} w(u).
\end{align*}
Hence,
\begin{equation}\label{E: upsilon estimate}
| \Upsilon( \alpha_m( \tilde \pi^{w(u)} x^u) ) | \leq | \tilde \pi |^{ \frac{p^{m-1}-1}{p^{m-1}} w(u)}
\end{equation}

The $R$-linear map $\psi_\lambda: \c S_0(\c O_{0, p}) \rightarrow \c S_0(\c O_0)$ is defined by 
\[
\psi_\lambda: \quad \sum_{\gamma \in M(\Gamma), \b u \in \c S(M)} A(\gamma, \b u)  \lambda^\gamma e_{\b u} \longmapsto \sum_{\gamma \in M(\Gamma), \b u \in \c S(M)} A(p \gamma, \b u)  \lambda^\gamma e_{\b u}
\]
We may in the usual manner view $\c S_0(\c O_0)$ as a $p$-adic Banach space over $R$ with orthonormal basis $\{ \tilde \pi^{w_\Gamma(\gamma)} \lambda^\gamma e_{\b u} \mid \gamma \in M(\Gamma), \b u \in \c S(M) \}$. Then 
\[
\beta_{\kappa, \bar t} := \psi_\lambda^{a d(\bar t)} \circ [\alpha_{a d(\bar t)}]_\kappa: \c S_0(\c O_0) \rightarrow \c S_0(\c O_0)
\]
is a completely continuous operator (over $R$).  Set $\c B := \{ e_{\b u} \mid  \b u \in \c S(M)\}$. Let $B^{[\kappa]}_{\bar t}(\lambda)$ be the matrix of $[\alpha_{a d(\bar t)}]_\kappa$ with respect to $\c B$, the basis of $\c S_0(\c O_0)$ over $\c O_0$ (as well as $\c S_0(\c O_{0, p^m})$ over $\c O_{0, p^m}$). The entries of $B_{\bar t}^{[\kappa]}(\lambda)$ are series with support in $\c B$ and coefficients in $\c O_{0, p^m}$ (which tend to 0 as $w(\b u) \rightarrow \infty$). We may write $B^{[\kappa]}_{\bar t}(\lambda) = \sum_{\gamma \in M(\Gamma)} b_\gamma^{[\kappa]} \lambda^\gamma$, where $b_\gamma^{[\kappa]}$ is a matrix with rows and columns indexed by $M(\Gamma)$ and entries in $R$. We define the matrix $F_{B^{[\kappa]}_{\bar t}} := (b_{q_{\bar t} \gamma - \mu}^{[\kappa]} )_{(\gamma, \mu)}$ indexed by $\gamma, \mu \in M(\Gamma)$, and we set $b_{q_{\bar t} \gamma - \mu}^{[\kappa]} := 0$ if $q_{\bar t} \gamma - \mu \not\in M(\Gamma)$. Note that $F_{B^{[\kappa]}_{\bar t}}$ is a matrix with entries in $R$ whose $(\gamma, \mu)$ entry is again a matrix in $R$ with rows and columns indexed by $M(\Gamma)$. As we showed in \cite[\S 2.3]{MR3239170}, $F_{B^{[\kappa]}_{\bar t}}$ is the matrix of the completely continuous operator $\beta_{\kappa, \bar t}$, and as such it has a well-defined Fredholm determinant. In particular, the Dwork trace formula gives
\begin{align*}
(q_{\bar t}^m - 1)^s Tr( \beta_{\kappa, \bar t}^m ) &= (q_{\bar t}^m - 1)^s Tr( F_{B^{[\kappa]}_{\bar t}}^m) \\
&= \sum_{\hat \lambda^{q_{\bar t}^m} = \hat \lambda} Tr \left( B^{[\kappa]}_{\bar t}(\hat \lambda^{q_{\bar t}^{m-1}}) \cdots B^{[\kappa]}_{\bar t}(\hat \lambda^{q_{\bar t}}) B^{[\kappa]}_{\bar t}(\hat \lambda) \right) \\
&= \sum_{\substack{ \bar \lambda \in (\bb F_{q_{\bar t}^m}^*)^s \\ \hat \lambda = \text{Teich}(\bar \lambda)}}  Tr \left( [ \alpha_{\bar t, \bar \lambda} ]_{\kappa}^m \mid \c S_0(\hat \lambda) \right).
\end{align*}

